#!/usr/bin/env python3
"""Class 3 EVS lessons and questions (English; Tamil to be added after review). Run from the project root: python3 tools/author_class3_evs.py"""
import os, sys
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from author_class3 import L, mcq, tf, num, short, order, lesson, W, D, CLR, write
T = []

def topic(chapter, slug, name_en, name_ta, objectives, les, qs):
    T.append(dict(chapter=chapter, topic=slug, name=L(name_en, name_ta), objectives=objectives, lesson=les, questions=qs))

topic("getting-to-know-plants", "parts-of-a-plant", "Parts of a plant", "செடியின் பாகங்கள்",
 ["Name the root, stem, leaf, flower and fruit of a plant", "Say what each part does for the plant"],
 lesson("Parts of a plant", "Ravi digs up a weed",
  "Ravi pulled a small weed out of the garden. Some earth came with it.\n\"Look, Amma! It has thin strings at the bottom, a thin body, and green flat parts!\"\nAmma smiled. \"Every part of a plant has a job. Let's find out what they do.\"",
  "A plant has parts.\nThe root grows under the ground. It holds the plant firmly and takes in water from the soil.\nThe stem holds the plant up and carries water to the leaves.\nThe leaves make food for the plant using sunlight.\nThe flower grows into a fruit. The fruit has seeds, and seeds grow into new plants.",
  ["root", "stem", "leaf", "flower", "fruit", "seed"],
  [("Look at a plant. The part under the ground is the root. It drinks water from the soil.", [CLR, D("line", "root"), W("root: holds and drinks")]),
   ("The stem stands above the ground. It holds the plant up and carries water to the leaves.", [D("line", "stem"), W("stem: holds up, carries water")]),
   ("The leaves are the kitchen of the plant. They use sunlight to make food.", [D("triangle", "leaf"), W("leaf: makes food")]),
   ("The flower becomes a fruit, and the fruit keeps the seeds safe for new plants.", [D("circle", "flower"), W("flower > fruit > seeds")])],
  "Which part of a tomato plant gives us the tomato, and which part took in the water?",
  [("The tomato is the fruit of the plant.", "Fruits grow from flowers."), ("Water is taken in by the roots from the soil.", "Roots grow under the ground and drink water."), ("So: the fruit gives the tomato, and the roots took in the water.", "Each part has its own job.")],
  "A friend says that leaves only make the plant look pretty. What will you tell your friend?",
  ["Leaves make food for the plant using sunlight.", "Roots take in water, and the stem carries it up."], ["Thinking plants get their food only from the soil."],
  ["r1-root", "r1-leaf", "r1-fruit-seeds"],
  ["Root: holds the plant and takes in water.", "Stem: holds the plant up and carries water.", "Leaf: makes food. Flower: becomes fruit with seeds."]),
 [mcq("r1-root", 1, "Which part of a plant grows under the ground?", "the root", [("the leaf", "Leaves are above the ground, in the sunlight."), ("the flower", "Flowers grow above the ground.")], "Roots grow in the soil.", "Think of pulling a weed.", 0),
  mcq("r1-leaf", 1, "Which part of a plant makes food using sunlight?", "the leaf", [("the root", "Roots take in water; they are in the dark soil."), ("the stem", "The stem carries water but does not make food.")], "Leaves use sunlight to make food.", "Which part is flat and green?", 1),
  tf("r1-fruit-seeds", 1, "A fruit has seeds that can grow into new plants.", True, "True. Seeds are inside the fruit."),
  mcq("r2-stem", 2, "What does the stem do?", "holds the plant up and carries water", [("makes seeds", "Seeds are made in flowers and fruits."), ("takes in water from the soil", "That is the job of the root.")], "The stem holds the plant up and carries water.", None, 2),
  tf("r2-flower", 2, "A flower can grow into a fruit.", True, "True. After a flower, a fruit with seeds can grow."),
  short("r2-take-water", 2, "Which part of the plant takes in water from the soil?", ["root", "roots", "the root"], "The root drinks water from the soil.", "It grows underground."),
  mcq("r3-carrot", 3, "We eat a carrot. Which part of the plant is it?", "the root", [("the fruit", "The carrot grows under the ground, so it is not a fruit."), ("the leaf", "A leaf is flat and green."), ("the flower", "A flower is not what we dig out of the soil.")], "A carrot is a root that grows under the ground.", "Where does a carrot grow?", 3),
  order("r3-order", 3, "Put these in order, from the one that grows first.", ["seed", "small plant", "flower", "fruit"], "A seed grows into a plant. The plant makes a flower, then a fruit."),
  tf("r3-soil-food", 3, "Plants get all their food from the soil.", False, "False. Leaves make food using sunlight, water and air."),
  mcq("r4-wilt", 4, "A plant is not watered for many days and its leaves droop. Which part could not bring water up?", "the root and stem", [("the flower only", "Water comes from the soil through the root and stem."), ("the fruit only", "Fruits do not carry water to the leaves.")], "Roots take in water and the stem carries it up. Without water, leaves droop.", "Which parts carry water?", 0),
  num("r4-parts", 4, "A plant has root, stem, leaf, flower and fruit. How many parts is that?", 5, "Count: root 1, stem 2, leaf 3, flower 4, fruit 5.", "Count each name once."),
  short("r4-pulled", 4, "Which part of a plant keeps the plant firmly in the soil?", ["root", "roots", "the root"], "The roots hold the plant firmly in the ground.", "It grows underground.")])

topic("water-a-precious-gift", "saving-water", "Saving water", "தண்ணீரைச் சேமித்தல்",
 ["Name where we get water and some ways we use it", "Give simple ways to save water at home and at school"],
 lesson("Saving water", "The dripping tap",
  "Meena heard a plink, plink, plink in the kitchen. A tap was dripping.\n\"It is only a few drops,\" said her brother.\nMeena put a bucket under it. By evening the bucket was half full!\n\"Little drops add up,\" she said.",
  "We get water from rivers, wells, ponds, rain and taps.\nWe use water for drinking, cooking, bathing, washing and watering plants.\nWater is precious. Clean water is not easy to find, and we must not waste it.\nWe can save water: close the tap while brushing, fix leaking taps, use a bucket to bathe, and reuse water to water plants.",
  ["water", "tap", "waste"],
  [("Where does water come from? From rivers, wells, ponds, rain, and then through pipes to our taps.", [CLR, W("rain, river, well, pond")]),
   ("We use water to drink, cook, wash and water plants. Every living thing needs water.", [W("we all need water")]),
   ("A dripping tap wastes many glasses of water every day. Fix it, or close it tightly.", [D("line", "tap"), W("close the tap")]),
   ("Brush with the tap closed. Bathe with a bucket. Water the plants with leftover water.", [W("save every drop")])],
  "Ravi lets the tap run for 2 minutes while brushing. Meena closes it. Who saves more water, and how?",
  [("Ravi keeps the tap open the whole time. Water flows and goes down the drain.", "Running water that nobody uses is wasted."), ("Meena closes the tap while brushing and opens it only to rinse.", "She uses only the water she needs."), ("So Meena saves more water.", "Closing the tap stops waste.")],
  "Your cousin leaves the tap running while she washes her hands with soap. What will you tell her?",
  ["Water is precious and we should not waste it.", "Close the tap while soaping, open it only to rinse."], ["Thinking a few drops do not matter."],
  ["r1-sources", "r1-tap", "r1-need"],
  ["We get water from rain, rivers, wells and ponds.", "Water is precious. Do not waste it.", "Close taps, fix leaks, use a bucket and reuse water."]),
 [mcq("r1-sources", 1, "Which of these gives us water?", "a well", [("a pillow", "A pillow does not give us water."), ("a stone", "A stone does not give us water.")], "Wells, rivers, ponds and rain give us water.", None, 1),
  tf("r1-tap", 1, "A dripping tap wastes water.", True, "True. Many drops add up to buckets of water."),
  tf("r1-need", 1, "Only people need water.", False, "False. Plants and animals need water too."),
  mcq("r2-brush", 2, "What should we do with the tap while brushing our teeth?", "close it", [("leave it open", "That wastes a lot of water."), ("open it fully", "That wastes even more water.")], "Close the tap and use water only to rinse.", None, 0),
  tf("r2-bucket", 2, "Bathing with a bucket uses less water than leaving the shower running.", True, "True. A bucket limits how much water we use."),
  short("r2-use", 2, "Name one thing we use water for.", ["drinking", "drink", "cooking", "cook", "bathing", "bath", "washing", "wash", "watering plants", "cleaning"], "We use water for drinking, cooking, bathing, washing and watering plants."),
  mcq("r3-reuse", 3, "Which is a good way to reuse water?", "water plants with the water used to wash vegetables", [("pour it on the road", "That wastes the water."), ("let it flow down the drain", "That wastes the water.")], "Water used to wash vegetables can water plants.", None, 2),
  order("r3-order", 3, "Put these in order: where drinking water comes from to your home.", ["rain falls", "water collects in a lake", "water comes through pipes", "water flows from the tap"], "Rain fills lakes, and pipes carry the water to our taps."),
  num("r3-glasses", 3, "A bucket holds 8 glasses of water. A dripping tap fills 2 buckets in a day. How many glasses is that?", 16, "8 + 8 = 16 glasses.", "Add 8 two times.", unit="glasses"),
  mcq("r4-plan", 4, "Which plan saves the most water in a family?", "fix leaking taps and close taps when not needed", [("wash the car every day", "That uses lots of water."), ("let the tap run while washing dishes", "That wastes water.")], "Stopping leaks and closing taps saves water every day.", None, 0),
  tf("r4-cleanwater", 4, "Clean water is easy to get everywhere, so we need not save it.", False, "False. In many places clean water is hard to find, so we must not waste it."),
  short("r4-where", 4, "Name a place where rain water collects.", ["pond", "lake", "river", "well", "tank", "ponds"], "Rain collects in ponds, lakes, rivers, wells and tanks.")])

topic("food-we-eat", "healthy-food", "Healthy food", "ஆரோக்கியமான உணவு",
 ["Name groups of healthy food", "Say why we eat different kinds of food"],
 lesson("Healthy food", "Asha's lunch box",
  "Asha opened her lunch box. There was rice, dal, a carrot, and a banana.\n\"Amma, why do you always put so many different things in?\" she asked.\nAmma said, \"Each food helps your body in a different way. Let's find out how.\"",
  "Food gives us energy to play and grow.\nCereals like rice, wheat and ragi give us energy.\nDal and pulses, milk and eggs help us grow strong.\nFruits and vegetables keep us healthy and help us fight illness.\nWe should eat a variety of food and drink clean water. Too many sweets or fried snacks are not good for us.",
  ["energy", "vegetable", "fruit"],
  [("Rice, chapati and ragi give us energy to run and play.", [CLR, W("rice, wheat, ragi = energy")]),
   ("Dal, milk and eggs help our bodies grow strong.", [W("dal, milk, egg = strong body")]),
   ("Fruits and vegetables help us stay healthy.", [W("fruit, vegetables = healthy")]),
   ("Eat many kinds of food. Sweets and fried snacks only a little.", [W("variety is best")])],
  "Sort these into foods that give energy and foods that keep us healthy: rice, banana, chapati, carrot.",
  [("Rice and chapati are cereals. They give us energy.", "Cereals give energy."), ("Banana and carrot are fruit and vegetable. They keep us healthy.", "Fruits and vegetables keep us healthy."), ("A good lunch box has both kinds.", "Variety is important.")],
  "Your friend only wants to eat chips and sweets. What will you tell your friend?",
  ["Different foods help the body in different ways.", "We should eat fruits, vegetables, dal and cereals, and little sweet or fried food."], ["Thinking one kind of food is enough."],
  ["r1-energy", "r1-fruit", "r1-water"],
  ["Cereals give energy. Dal, milk and eggs help us grow. Fruits and vegetables keep us healthy.", "Eat many kinds of food.", "Sweets and fried snacks only a little."]),
 [mcq("r1-energy", 1, "Which food gives us energy?", "rice", [("a pencil", "A pencil is not food."), ("a stone", "A stone is not food.")], "Cereals like rice give us energy.", None, 0),
  tf("r1-fruit", 1, "Fruits and vegetables keep us healthy.", True, "True. They help the body stay strong and fight illness."),
  tf("r1-water", 1, "We should drink clean water every day.", True, "True. Our body needs clean water."),
  mcq("r2-dal", 2, "Which of these helps us grow strong?", "dal", [("a lollipop", "Sweets do not help the body grow strong."), ("a bag of chips", "Chips are not a healthy way to grow strong.")], "Dal, milk and eggs help us grow strong.", None, 1),
  tf("r2-one", 2, "Eating only one kind of food is best.", False, "False. We need many kinds of food."),
  short("r2-cereal", 2, "Name one cereal.", ["rice", "wheat", "ragi", "maize", "millet", "bajra", "jowar", "oats"], "Rice, wheat, ragi and maize are cereals."),
  mcq("r3-box", 3, "Which lunch box is the healthiest?", "chapati, dal, carrot and a banana", [("chips and a cold drink", "That has too much fried and sugary food."), ("only biscuits", "That is not enough variety."), ("only sweets", "Sweets are not healthy to eat all the time.")], "It has cereal, dal, a vegetable and a fruit.", None, 1),
  order("r3-order", 3, "Put the meals of a day in order, from the morning.", ["breakfast", "lunch", "dinner"], "We eat breakfast in the morning, lunch at noon and dinner at night.", None),
  num("r3-meals", 3, "Ravi eats 3 meals a day. How many meals does he eat in 2 days?", 6, "3 + 3 = 6 meals.", "Add 3 two times."),
  mcq("r4-why", 4, "Why do we eat different kinds of food?", "each kind helps our body in a different way", [("because it is boring to eat one", "The real reason is the body needs many things."), ("because food is free", "That is not the reason.")], "Different foods give energy, growth and health.", None, 2),
  tf("r4-sweets", 4, "It is fine to eat sweets all day instead of meals.", False, "False. Sweets do not give the body all it needs."),
  short("r4-fruit", 4, "Name one fruit.", ["banana", "mango", "apple", "orange", "guava", "papaya", "grapes", "pomegranate", "jackfruit", "watermelon"], "Banana, mango, apple and guava are fruits.")])

topic("staying-healthy-and-happy", "keeping-clean", "Keeping clean", "தூய்மையாக இருத்தல்",
 ["Name habits that keep the body clean", "Explain why washing hands and brushing teeth matter"],
 lesson("Keeping clean", "Kabir's muddy hands",
  "Kabir came home from cricket with muddy hands. He reached for a biscuit.\n\"Stop!\" said Amma. \"What do we do first?\"\n\"Wash my hands with soap!\" said Kabir. He had almost forgotten.",
  "Germs are tiny living things we cannot see. Some of them make us ill.\nWashing hands with soap and water removes germs. Wash before eating and after using the toilet or playing outside.\nBrush the teeth twice a day: in the morning and at night.\nBathe every day, cut nails, wear clean clothes, and sleep enough.\nThese habits keep us healthy and happy.",
  ["germs", "soap", "brush"],
  [("Germs are so small that we cannot see them. Some can make us ill.", [CLR, W("germs make us ill")]),
   ("Wash your hands with soap before eating and after playing or using the toilet.", [W("wash hands: before eating")]),
   ("Brush your teeth in the morning and at night. Bathe every day.", [W("brush twice a day")]),
   ("Clean habits keep the body healthy, and a healthy body is a happy one.", [W("clean = healthy = happy")])],
  "Kabir's hands are muddy and he wants to eat. What should he do first, and why?",
  [("Wash his hands with soap and water.", "Soap and water remove mud and germs."), ("Rub them well, front and back, between the fingers.", "Germs hide in small places."), ("Then dry them and eat.", "Clean hands keep germs out of our mouths.")],
  "Your younger sister says she can eat without washing hands, because the mud is dry. What will you tell her?",
  ["Germs are too small to see.", "Wash hands with soap and water before eating."], ["Thinking hands are clean if no mud can be seen."],
  ["r1-soap", "r1-teeth", "r1-germs"],
  ["Wash hands with soap before eating and after playing or using the toilet.", "Brush teeth twice a day, bathe every day.", "Clean habits keep us healthy."]),
 [mcq("r1-soap", 1, "What should we use to wash our hands properly?", "soap and water", [("only a dry cloth", "A dry cloth does not remove germs."), ("sand", "Sand is not clean.")], "Soap and water remove germs.", None, 1),
  num("r1-teeth", 1, "How many times a day should we brush our teeth?", 2, "Brush in the morning and at night: 2 times.", "Morning and night."),
  tf("r1-germs", 1, "Germs are so small that we cannot see them.", True, "True. We cannot see them, but they are there."),
  mcq("r2-when", 2, "When should we wash our hands?", "before eating", [("only when they look dirty", "Germs cannot be seen, so wash before eating always."), ("never", "We must wash to stay healthy.")], "Wash before eating and after using the toilet or playing.", None, 0),
  tf("r2-nails", 2, "Long dirty nails can hold germs.", True, "True. Keep nails short and clean."),
  short("r2-bath", 2, "How often should we bathe: every day or once a month?", ["every day", "everyday", "daily", "each day"], "Bathe every day to stay clean and fresh.", None),
  mcq("r3-toilet", 3, "What should we do after using the toilet?", "wash our hands with soap", [("eat something", "We must wash our hands first."), ("go back to class without washing", "Germs from the toilet can spread.")], "Always wash hands with soap after the toilet.", None, 2),
  order("r3-order", 3, "Put these in order before lunch.", ["play outside", "wash hands with soap", "sit down to eat"], "After play we wash hands with soap, and then we eat.", None),
  num("r3-brush", 3, "Meena brushes twice a day. How many times does she brush in 3 days?", 6, "2 + 2 + 2 = 6 times.", "Add 2 three times."),
  mcq("r4-cold", 4, "Why is it good to cover our mouth when we sneeze?", "so germs do not spread to others", [("because it is polite only", "It is polite, but the main reason is health."), ("because it feels warm", "That is not the reason.")], "Covering our mouth stops germs from spreading.", None, 0),
  tf("r4-sleep", 4, "Sleeping enough helps us stay healthy.", True, "True. Our body rests and grows while we sleep."),
  short("r4-habit", 4, "Name one habit that keeps us clean.", ["washing hands", "brushing teeth", "bathing", "wash hands", "brush teeth", "bath", "cutting nails", "wearing clean clothes"], "Washing hands, brushing teeth and bathing keep us clean.")])

topic("taking-charge-of-waste", "reduce-reuse-recycle", "Reduce, reuse, recycle", "குறைத்தல், மறுபயன்பாடு, மறுசுழற்சி",
 ["Explain what waste is and name wet and dry waste", "Give examples of reducing, reusing and recycling"],
 lesson("Reduce, reuse, recycle", "Riya's class cleans up",
  "At lunch the playground was full of paper, peels and plastic wrappers.\n\"Who dropped all this?\" asked Riya's teacher.\nThe class decided to clean up. They used two bins: one for peels and leaves, one for paper and plastic.",
  "Things we throw away are waste.\nWet waste comes from plants and food: peels, leaves, leftover food. It can become compost for plants.\nDry waste is paper, plastic, glass and metal.\nWe can reduce waste by using less. We can reuse things, like writing on both sides of paper or using a cloth bag. We can recycle: old paper and bottles can be made into new things.\nNever throw waste on the road or in water. Use a dustbin.",
  ["waste", "recycle", "reuse"],
  [("Waste is what we throw away. Wet waste is food and plant waste, like peels and leaves.", [CLR, W("wet waste: peels, leaves")]),
   ("Dry waste is paper, plastic, glass and metal. Keep them in a separate bin.", [W("dry waste: paper, plastic")]),
   ("Reduce: use less. Reuse: use again. Recycle: make something new from old.", [W("reduce, reuse, recycle")]),
   ("Always put waste in a dustbin. A clean place is a happy place.", [W("use the dustbin")])],
  "A banana peel, an old newspaper and a plastic bottle: which are wet waste and which are dry?",
  [("The banana peel comes from food. It is wet waste.", "Wet waste comes from food and plants."), ("The newspaper and plastic bottle are dry waste.", "Paper and plastic are dry waste."), ("Keep them in separate bins.", "Separating helps us reuse and recycle.")],
  "A friend throws a wrapper on the ground because 'it is only one'. What will you tell your friend?",
  ["Waste should go into a dustbin.", "Many small wrappers make a big mess; reduce, reuse and recycle."], ["Thinking one wrapper does not matter."],
  ["r1-wet", "r1-bin", "r1-dry"],
  ["Wet waste is from food and plants; dry waste is paper, plastic, glass and metal.", "Reduce, reuse, recycle.", "Put waste in a dustbin."]),
 [mcq("r1-wet", 1, "Which of these is wet waste?", "a banana peel", [("a plastic bottle", "Plastic is dry waste."), ("an old newspaper", "Paper is dry waste.")], "Peels and leftover food are wet waste.", None, 0),
  tf("r1-bin", 1, "We should put waste in a dustbin.", True, "True. Never throw waste on the road or in water."),
  mcq("r1-dry", 1, "Which of these is dry waste?", "paper", [("vegetable peel", "That is wet waste."), ("leftover rice", "That is wet waste.")], "Paper, plastic, glass and metal are dry waste.", None, 1),
  mcq("r2-reuse", 2, "Which is an example of reusing?", "using an old jar to keep pencils", [("throwing the jar away", "That is wasting, not reusing."), ("breaking the jar", "That is not reusing.")], "Using something again for a new purpose is reusing.", None, 0),
  tf("r2-compost", 2, "Wet waste like peels can become compost for plants.", True, "True. Compost helps plants grow."),
  short("r2-three", 2, "What are the three Rs? Name one of them.", ["reduce", "reuse", "recycle"], "The three Rs are reduce, reuse and recycle.", None),
  mcq("r3-bag", 3, "Which saves more waste: a cloth bag or a new plastic bag every time?", "a cloth bag", [("a new plastic bag every time", "That makes much more waste.")], "A cloth bag can be used again and again.", None, 0),
  order("r3-order", 3, "Put these in order, from using the least to the most waste.", ["bring a cloth bag", "use paper bags", "take a new plastic bag every time"], "A cloth bag makes the least waste; a new plastic bag every time makes the most.", None),
  num("r3-bins", 3, "The class has 2 bins. Each bin is emptied 3 times a week. How many times is a bin emptied in all?", 6, "2 + 2 + 2 = 6 times.", "Add 2 three times."),
  mcq("r4-paper", 4, "A page is written only on one side. How can you reduce waste?", "write on the other side too", [("throw it away", "That makes waste."), ("tear it up", "That wastes paper.")], "Using both sides uses less paper.", None, 0),
  tf("r4-water", 4, "It is fine to throw waste into a pond.", False, "False. It makes the water dirty and harms animals."),
  short("r4-recycle", 4, "Name one thing that can be recycled.", ["paper", "plastic", "glass", "metal", "bottle", "bottles", "newspaper", "cans"], "Paper, glass, metal and some plastic can be recycled.")])

if __name__ == "__main__":
    write(T, "evs")
    print("written", len(T), "evs topics")
